const fs = await import("fs");
const path = await import("path");
const fp = path.join($root, "packages/main/tests/fixtures/_test_reorder_migrate.json");
// B 在 index 0, A 在 index 1
fs.writeFileSync(fp, JSON.stringify({cases:[
  {name:"B_first",run_type:"cli",fn:"story_get",file:"mcp/handlers/story",execute:"return 'B'"},
  {name:"A_second",run_type:"cli",fn:"story_get",file:"mcp/handlers/story",execute:"return 'A'"}
]},null,2));
$handlers.fixture_migrate();
const content = JSON.parse(fs.readFileSync(fp, "utf-8"));
// 链关系应按数组顺序：B→A
const ok = content.cases[0].nextCaseId === content.cases[1]._id && content.cases[1].prevCaseId === content.cases[0]._id;
return ok ? "reorder_chain_ok" : "wrong_order"

